-- Name: bill_payments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.bill_payments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    restaurant_id uuid NOT NULL,
    bill_id uuid NOT NULL,
    mode public.bill_payment_mode NOT NULL,
    share_index smallint,
    share_count smallint,
    amount_minor integer NOT NULL,
    method public.bill_payment_method NOT NULL,
    status public.bill_payment_status NOT NULL,
    payment_id uuid,
    member_id uuid,
    recorded_by_user_id uuid,
    expires_at timestamp with time zone,
    settled_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT bill_payments_amount_positive CHECK ((amount_minor > 0)),
    CONSTRAINT bill_payments_method CHECK ((((method = 'online'::public.bill_payment_method) AND ((payment_id IS NOT NULL) OR (status <> 'succeeded'::public.bill_payment_status))) OR ((method <> 'online'::public.bill_payment_method) AND (payment_id IS NULL) AND (recorded_by_user_id IS NOT NULL)))),
    CONSTRAINT bill_payments_share CHECK ((((mode = 'equal'::public.bill_payment_mode) = ((share_index IS NOT NULL) AND (share_count IS NOT NULL))) AND ((share_count IS NULL) OR (((share_count >= 2) AND (share_count <= 20)) AND ((share_index >= 1) AND (share_index <= share_count))))))
);


--
-- Name: bills; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.bills (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    restaurant_id uuid NOT NULL,
    location_id uuid NOT NULL,
    table_id uuid NOT NULL,
    table_session_id uuid NOT NULL,
    status public.bill_status DEFAULT 'open'::public.bill_status NOT NULL,
    currency text NOT NULL,
    subtotal_minor integer DEFAULT 0 NOT NULL,
    discount_minor integer DEFAULT 0 NOT NULL,
    service_fee_bps smallint DEFAULT 0 NOT NULL,
    service_fee_minor integer DEFAULT 0 NOT NULL,
    tax_included_minor integer DEFAULT 0 NOT NULL,
    total_minor integer DEFAULT 0 NOT NULL,
    paid_minor integer DEFAULT 0 NOT NULL,
    finalized_at timestamp with time zone,
    finalized_by_user_id uuid,
    paid_at timestamp with time zone,
    voided_at timestamp with time zone,
    void_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    vat_rate_bps smallint DEFAULT 0 NOT NULL,
    CONSTRAINT bills_amounts CHECK (((subtotal_minor >= 0) AND (discount_minor >= 0) AND (discount_minor <= subtotal_minor) AND (service_fee_minor >= 0) AND (tax_included_minor >= 0) AND (tax_included_minor <= total_minor))),
    CONSTRAINT bills_currency_format CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT bills_paid_means_settled CHECK (((status <> 'paid'::public.bill_status) OR ((paid_minor = total_minor) AND (paid_at IS NOT NULL)))),
    CONSTRAINT bills_paid_range CHECK (((paid_minor >= 0) AND (paid_minor <= total_minor))),
    CONSTRAINT bills_service_fee_rate CHECK (((service_fee_bps >= 0) AND (service_fee_bps <= 3000))),
    CONSTRAINT bills_total CHECK ((total_minor = ((subtotal_minor - discount_minor) + service_fee_minor))),
    CONSTRAINT bills_void_unpaid CHECK (((status <> 'void'::public.bill_status) OR ((paid_minor = 0) AND (void_reason IS NOT NULL))))
);


