    CONSTRAINT orders_idempotency_key CHECK (((length(idempotency_key) >= 8) AND (length(idempotency_key) <= 100))),
    CONSTRAINT orders_number_positive CHECK ((number > 0)),
    CONSTRAINT orders_total CHECK ((total_minor = (subtotal_minor - discount_minor)))
);


