);


--
-- Name: restaurant_locations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.restaurant_locations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    restaurant_id uuid NOT NULL,
    name text NOT NULL,
    slug text NOT NULL,
    status public.location_status DEFAULT 'active'::public.location_status NOT NULL,
    address_line text NOT NULL,
    city text NOT NULL,
    country text DEFAULT 'AM'::text NOT NULL,
    postal_code text,
    latitude double precision,
    longitude double precision,
    phone text,
    timezone text DEFAULT 'Asia/Yerevan'::text NOT NULL,
    opening_hours jsonb DEFAULT '{"fri": [], "mon": [], "sat": [], "sun": [], "thu": [], "tue": [], "wed": []}'::jsonb NOT NULL,
    reservations_enabled boolean DEFAULT false NOT NULL,
    sort_order integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    reservation_confirmation public.reservation_confirmation_mode DEFAULT 'manual'::public.reservation_confirmation_mode NOT NULL,
    reservation_duration_minutes smallint DEFAULT 120 NOT NULL,
    reservation_min_notice_minutes integer DEFAULT 60 NOT NULL,
    reservation_max_days_ahead smallint DEFAULT 30 NOT NULL,
    reservation_deposit_type public.reservation_deposit_type DEFAULT 'none'::public.reservation_deposit_type NOT NULL,
    reservation_deposit_minor integer DEFAULT 0 NOT NULL,
    reservation_refund_cutoff_hours smallint DEFAULT 24 NOT NULL,
    service_fee_bps smallint DEFAULT 0 NOT NULL,
    CONSTRAINT restaurant_locations_coordinates CHECK ((((latitude IS NULL) AND (longitude IS NULL)) OR ((latitude IS NOT NULL) AND (longitude IS NOT NULL) AND ((latitude >= ('-90'::integer)::double precision) AND (latitude <= (90)::double precision)) AND ((longitude >= ('-180'::integer)::double precision) AND (longitude <= (180)::double precision))))),
    CONSTRAINT restaurant_locations_country_format CHECK ((country ~ '^[A-Z]{2}$'::text)),
    CONSTRAINT restaurant_locations_deposit CHECK ((((reservation_deposit_type = 'none'::public.reservation_deposit_type) OR (reservation_deposit_minor > 0)) AND ((reservation_deposit_minor >= 0) AND (reservation_deposit_minor <= 100000000)) AND ((reservation_refund_cutoff_hours >= 0) AND (reservation_refund_cutoff_hours <= 168)))),
    CONSTRAINT restaurant_locations_reservation_settings CHECK ((((reservation_duration_minutes >= 30) AND (reservation_duration_minutes <= 360)) AND ((reservation_min_notice_minutes >= 0) AND (reservation_min_notice_minutes <= 10080)) AND ((reservation_max_days_ahead >= 1) AND (reservation_max_days_ahead <= 365)))),
    CONSTRAINT restaurant_locations_service_fee CHECK (((service_fee_bps >= 0) AND (service_fee_bps <= 3000))),
    CONSTRAINT restaurant_locations_slug_format CHECK ((slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'::text))
);


