    CONSTRAINT restaurants_slug_format CHECK ((slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'::text)),
    CONSTRAINT restaurants_vat_rate CHECK (((vat_rate_bps >= 0) AND (vat_rate_bps <= 5000)))
