--
-- Name: reviews; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.reviews (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    restaurant_id uuid NOT NULL,
    location_id uuid NOT NULL,
    subject public.review_subject NOT NULL,
    reservation_id uuid,
    table_session_id uuid,
    author_user_id uuid,
    author_guest_id uuid,
    author_email text,
    display_name text NOT NULL,
    rating smallint NOT NULL,
    comment text,
    status public.review_status DEFAULT 'published'::public.review_status NOT NULL,
    published_at timestamp with time zone,
    moderated_by_user_id uuid,
    moderated_at timestamp with time zone,
    moderation_reason text,
    response text,
    responded_at timestamp with time zone,
    responded_by_user_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    reported_at timestamp with time zone,
    reported_by_user_id uuid,
    report_reason text,
    author_email_verified_at timestamp with time zone,
    email_token_hash text,
    CONSTRAINT reviews_author CHECK ((NOT ((author_user_id IS NOT NULL) AND (author_guest_id IS NOT NULL)))),
    CONSTRAINT reviews_comment_length CHECK (((comment IS NULL) OR (length(comment) <= 2000))),
    CONSTRAINT reviews_display_name CHECK (((length(TRIM(BOTH FROM display_name)) >= 1) AND (length(TRIM(BOTH FROM display_name)) <= 60))),
    CONSTRAINT reviews_email_lowercase CHECK (((author_email IS NULL) OR (author_email = lower(author_email)))),
    CONSTRAINT reviews_guest_email CHECK (((author_guest_id IS NULL) OR (author_email IS NOT NULL))),
    CONSTRAINT reviews_rating CHECK (((rating >= 1) AND (rating <= 5))),
    CONSTRAINT reviews_report_reason CHECK (((reported_at IS NULL) OR ((length(TRIM(BOTH FROM report_reason)) >= 10) AND (length(TRIM(BOTH FROM report_reason)) <= 500)))),
    CONSTRAINT reviews_response_length CHECK (((response IS NULL) OR (length(response) <= 2000))),
    CONSTRAINT reviews_subject_target CHECK ((((subject = 'reservation'::public.review_subject) AND (reservation_id IS NOT NULL) AND (table_session_id IS NULL)) OR ((subject = 'visit'::public.review_subject) AND (table_session_id IS NOT NULL) AND (reservation_id IS NULL))))
);


